function base64UrlDecode(str){let b64 = str.replace(/-/g, "+").replace(/_/g, "/");while (b64.length % 4) b64 += "=";const binary = atob(b64);const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));return new TextDecoder("utf-8").decode(bytes);}const JWT_TIME_CLAIMS = ["exp", "iat", "nbf"];function annotateTimeClaims(payload){const notes = [];for (const claim of JWT_TIME_CLAIMS){if (typeof payload[claim] === "number"){const d = new Date(payload[claim] * 1000);const expired = claim === "exp" && d.getTime() < Date.now();notes.push(`${claim}: ${d.toISOString()}${expired ? " (EXPIRED)" : ""}`);}}return notes;}function decodeJwt(token){const parts = token.trim().split(".");if (parts.length !== 3) return{error: "not a JWT - expected 3 dot-separated parts (header.payload.signature)"};const [headerB64, payloadB64, signature] = parts;let header, payload;try{header = JSON.parse(base64UrlDecode(headerB64));}catch (e){return{error: "header isn't valid base64url JSON: " + e.message};}try{payload = JSON.parse(base64UrlDecode(payloadB64));}catch (e){return{error: "payload isn't valid base64url JSON: " + e.message};}return{header, payload, signature, timeNotes: annotateTimeClaims(payload)};}function executeJwtDecode(){const raw = document.getElementById("jwt-input").value;const out = document.getElementById("jwt-result");if (!raw.trim()){out.innerHTML = "";GAMA.say("idle");return;}const result = decodeJwt(raw);if (result.error){GAMA.say("error");out.textContent = `// ${result.error}`;GAMA.log(`JWT decode failed: ${result.error}`);return;}GAMA.say("success");let html = `<div style="color:var(--phosphor-dim); margin-bottom:0.3rem;">header:</div><pre style="margin:0 0 1rem; white-space:pre-wrap;">${escapeJwtHtml(JSON.stringify(result.header, null, 2))}</pre>`;html += `<div style="color:var(--phosphor-dim); margin-bottom:0.3rem;">payload:</div><pre style="margin:0 0 1rem; white-space:pre-wrap;">${escapeJwtHtml(JSON.stringify(result.payload, null, 2))}</pre>`;if (result.timeNotes.length){html += `<div style="color:var(--phosphor-dim); margin-bottom:0.3rem;">time claims:</div><div style="margin-bottom:1rem;">${result.timeNotes.map(escapeJwtHtml).join("<br>")}</div>`;}html += `<div style="color:var(--phosphor-dim); margin-bottom:0.3rem;">signature (not verified — that needs the secret, which never belongs in a browser tab):</div><div style="word-break:break-all;">${escapeJwtHtml(result.signature)}</div>`;out.innerHTML = html;GAMA.log("JWT decoded, signature not verified (by design)");}function escapeJwtHtml(s){return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");}